#include "qupathxx/linear_unmixing.hpp"
#include "qupathxx/source_identity.hpp"
#include "qupathxx/workflow.hpp"
#include <algorithm>
#include <iostream>
using namespace qpx;
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
template<class E=std::exception,class F>void rejects(F f){try{f();}catch(const E&){return;}throw std::runtime_error("Expected linear unmixing refusal");}
void expect_close(double a,double b){check(std::isfinite(a) && std::abs(a-b)<=1e-11*std::max(1.0,std::abs(b)),"Unmixing differs from independent analytical oracle");}
LinearMixingMatrix matrix(){LinearMixingMatrix p;p.inputs={{2,"C2"},{7,"C7"}};p.components={"A","B"};p.coefficients={1,.25,.5,1};return p;}
RawPixelBuffer block(std::initializer_list<double> values){RawPixelBuffer out(1,1,std::uint32_t(values.size()),SampleType::Float64);std::get<std::vector<double>>(out.writable_storage())=values;out.writable_valid()[0]=1;return out;}
const std::vector<double>& values(const RawPixelBuffer& out){return std::get<std::vector<double>>(out.storage());}
class Reader final:public ImageServer {
public:
    RawImageMetadata raw;ImageMetadata display;std::shared_ptr<const ReaderSource> observed=make_reader_source("unmix-reference","","memory");
    int role=0;std::uint32_t second=7;bool is_closed=false,wrong_shape=false;mutable bool change=false;std::atomic<bool>* cancel_on_read=nullptr;
    mutable std::vector<std::pair<std::uint32_t,std::uint32_t>> reads;
    explicit Reader(int r=0):role(r){raw.width=5;raw.height=3;raw.channels=10;raw.z_planes=raw.timepoints=2;raw.sample_type=SampleType::Float64;raw.levels={{5,3,1}};raw.pixel_width_um=.5;raw.pixel_height_um=1;raw.dimension_order="XYZCT";for(int i=0;i<10;++i)raw.channel_names.push_back("C"+std::to_string(i));display.width=5;display.height=3;display.levels=raw.levels;}
    const ImageMetadata& metadata()const override{return display;}
    std::string reader_id()const override{return "unmix-reference";}
    std::shared_ptr<const ReaderSource> reader_source()const override{return observed;}
    std::shared_ptr<const RawImageMetadata> raw_metadata(const std::atomic<bool>*)const override{return std::make_shared<const RawImageMetadata>(raw);}
    PixelBuffer read_region(const RegionRequest&)const override{throw std::runtime_error("RGB is not an unmixing input");}
    RawPixelBuffer read_raw(const RawRegionRequest& r,const std::atomic<bool>* cancelled)const override{workflow_checkpoint(cancelled);reads.emplace_back(r.first_channel,r.channels);for(std::uint32_t c=0;c<r.channels;++c)if(r.first_channel+c!=2 && r.first_channel+c!=second)throw std::runtime_error("Sparse unmixing must not read channel gaps");
        RawPixelBuffer out(r.region.width+(wrong_shape?1:0),r.region.height,r.channels,SampleType::Float64);auto& result=std::get<std::vector<double>>(out.writable_storage());for(std::int64_t y=0;y<r.region.height;++y)for(std::int64_t x=0;x<r.region.width;++x){auto gx=x+r.region.x,gy=y+r.region.y;const auto at=std::size_t(y*r.region.width+x);out.writable_valid()[at]=gx>=0 && gy>=0 && gx<5 && gy<3 && !(gx==0 && gy==0);const double a=(gx-2)*10+3*r.z+5*r.t,b=gy*4-6+2*r.z+7*r.t;for(std::uint32_t c=0;c<r.channels;++c)result[at*r.channels+c]=role?double(role):r.first_channel+c==2?a+.25*b:.5*a+b;}
        if(change){change=false;const_cast<Reader*>(this)->raw.pixel_width_um=2;}if(cancel_on_read)cancel_on_read->store(true);return out;
    }
    void close()override{is_closed=true;}bool closed()const override{return is_closed;}
};
void schema(){auto p=matrix();p.validate();check(p.output_names()==std::vector<std::string>{"A","B","residual:C2","residual:C7"},"Output names separate components and residuals");auto copy=p;check(copy.sha256()==p.sha256(),"Exact recipe identity stable");copy.coefficients[1]=-0.0;auto zero=copy;zero.coefficients[1]=0;check(copy.sha256()!=zero.sha256(),"Signed coefficient zero retained in exact recipe identity");
    for(int i=0;i<10;++i){auto bad=p;if(i==0)bad.coefficients[0]=NAN;else if(i==1)bad.coefficients.pop_back();else if(i==2)bad.inputs[1].channel=2;else if(i==3)bad.inputs[0].channel=65536;else if(i==4)bad.components[1]="A";else if(i==5)bad.maximum_condition=.5;else if(i==6)bad.maximum_condition=1e13;else if(i==7)bad.input_domain="display-rgb";else if(i==8)bad.components[0]="residual:C2";else bad.inputs.resize(1);rejects<std::invalid_argument>([&]{bad.validate();});}
}
void records(){using V=ImageDataValue;auto p=matrix();p.coefficients[1]=-0.0;auto encoded=p.to_value();auto restored=LinearMixingMatrix::from_value(encoded);check(restored.sha256()==p.sha256() && std::signbit(restored.coefficients[1]),"Typed matrix retains exact coefficient bits and identity");
    ImageDataProperties props(V::Map{{"matrix",encoded}});check(LinearMixingMatrix::from_value(props.values().at("matrix")).sha256()==p.sha256(),"Matrix fits existing immutable native properties");
    for(int i=0;i<16;++i){auto bad=encoded;auto& m=std::get<V::Map>(bad.value);
        if(i==0)m.erase("orientation");else if(i==1)m["extra"]=V{true};else if(i==2)m["schema"]=V{std::string("qpx.linear-mixing-matrix/2")};else if(i==3)m["orientation"]=V{std::string("components=matrix*measured")};
        else if(i==4)m["input_domain"]=V{std::string("display-rgb")};else if(i==5)m["maximum_condition"]=V{std::int64_t(100)};else if(i==6)m["coefficients"]=V{V::List{}};
        else if(i==7)std::get<V::List>(m.at("components").value).clear();else if(i==8)std::get<V::List>(m.at("inputs").value).resize(65);
        else if(i==9)std::get<V::List>(m.at("coefficients").value)[0]=V{NAN};else if(i==10)std::get<V::List>(m.at("coefficients").value)[0]=V{std::int64_t(1)};
        else if(i==11)std::get<V::Map>(std::get<V::List>(m.at("inputs").value)[0].value)["channel"]=V{std::int64_t(-1)};
        else if(i==12)std::get<V::Map>(std::get<V::List>(m.at("inputs").value)[0].value)["channel"]=V{2.0};
        else if(i==13)std::get<V::Map>(std::get<V::List>(m.at("inputs").value)[0].value)["extra"]=V{true};
        else if(i==14)std::get<V::List>(m.at("components").value)[0]=V{std::string(97,'x')};else m["inputs"]=V{false};
        rejects<std::invalid_argument>([&]{LinearMixingMatrix::from_value(bad);});}
    rejects<std::invalid_argument>([]{LinearMixingMatrix::from_value(V{false});});
    auto limit=matrix();limit.inputs.clear();limit.components.clear();limit.coefficients.assign(64*64,0);for(std::uint32_t i=0;i<64;++i){limit.inputs.push_back({i,"C"+std::to_string(i)});limit.components.push_back("S"+std::to_string(i));limit.coefficients[i*64+i]=1;}
    ImageDataProperties maximum(V::Map{{"matrix",limit.to_value()}});check(LinearMixingMatrix::from_value(maximum.values().at("matrix")).sha256()==limit.sha256(),"Maximum matrix fits native property limits without densifying beyond declared shape");
}
void numeric(){const LinearUnmixModel model(matrix());check(model.condition()>1 && model.condition()<3,"Analytical well-conditioned matrix");auto measured=block({9,1});auto out=linear_unmix_block(measured,model);expect_close(values(out)[0],10);expect_close(values(out)[1],-4);expect_close(values(out)[2],0);expect_close(values(out)[3],0);
    for(std::uint32_t c=0;c<4;++c){auto part=linear_unmix_block(measured,model,c,1);check(values(part)[0]==values(out)[c],"Requested output slice exactly equals full solve");}
    LinearMixingMatrix rectangular;rectangular.inputs={{0,"U"},{1,"V"},{2,"W"}};rectangular.components={"A","B"};rectangular.coefficients={1,0,0,1,1,1};const LinearUnmixModel fit(rectangular);auto noisy=linear_unmix_block(block({2,3,6}),fit);expect_close(values(noisy)[0],7./3);expect_close(values(noisy)[1],10./3);expect_close(values(noisy)[2],-1./3);expect_close(values(noisy)[3],-1./3);expect_close(values(noisy)[4],1./3);
    auto columns=rectangular;columns.components={"B","A"};columns.coefficients={0,1,1,0,1,1};auto swapped=linear_unmix_block(block({2,3,6}),LinearUnmixModel(columns));expect_close(values(swapped)[0],10./3);expect_close(values(swapped)[1],7./3);
    for(double scale:{1e-150,1e150}){auto scaled=matrix();for(auto& v:scaled.coefficients)v*=scale;auto result=linear_unmix_block(block({9*scale,scale}),LinearUnmixModel(scaled));expect_close(values(result)[0],10);expect_close(values(result)[1],-4);}
    auto singular=matrix();singular.coefficients={1,1,1,1};rejects<std::invalid_argument>([&]{LinearUnmixModel bad(singular);});singular.coefficients={1,0,0,1e-9};singular.maximum_condition=1e8;rejects<std::invalid_argument>([&]{LinearUnmixModel bad(singular);});singular.maximum_condition=1e10;check(LinearUnmixModel(singular).condition()>1e8,"Explicit condition policy admits declared larger condition");
    auto tiny=matrix();tiny.coefficients={1e-300,0,0,1e-300};auto overflow=linear_unmix_block(block({1e100,0}),LinearUnmixModel(tiny));check(std::isnan(values(overflow)[0]) && values(overflow)[1]==0 && std::isnan(values(overflow)[2]) && std::isnan(values(overflow)[3]),"Overflow remains per-component unknown with unknown residuals, never clamped");
    auto invalid=linear_unmix_block(block({NAN,1}),model);check(invalid.valid()[0] && std::all_of(values(invalid).begin(),values(invalid).end(),[](double v){return std::isnan(v);}),"Nonfinite required input makes coupled outputs unknown");measured.writable_valid()[0]=0;auto absent=linear_unmix_block(measured,model);check(!absent.valid()[0],"Missing source pixel is not a true zero");
    rejects<WorkflowCaptureLimit>([&]{linear_unmix_block(block({9,1}),model,0,0,1);});rejects<std::invalid_argument>([&]{linear_unmix_block(block({9}),model);});
    RawPixelBuffer huge(1,1,2,SampleType::UInt64);huge.writable_valid()[0]=1;std::get<std::vector<std::uint64_t>>(huge.writable_storage())={(std::uint64_t(1)<<53)+1,0};rejects<std::overflow_error>([&]{linear_unmix_block(huge,model);});
    RawPixelBuffer signed_huge(1,1,2,SampleType::Int64);signed_huge.writable_valid()[0]=1;std::get<std::vector<std::int64_t>>(signed_huge.writable_storage())={-(std::int64_t(1)<<53)-1,0};rejects<std::overflow_error>([&]{linear_unmix_block(signed_huge,model);});
    auto malformed=block({9,1});malformed.writable_storage()=std::vector<float>{9,1};rejects<WorkflowInputChanged>([&]{linear_unmix_block(malformed,model);});
    std::atomic<bool> cancel{true};rejects<WorkflowCancelled>([&]{LinearUnmixModel stopped(matrix(),&cancel);});rejects<WorkflowCancelled>([&]{linear_unmix_block(block({9,1}),model,0,0,256u*1024*1024,&cancel);});
}
void sources(){auto reader=std::make_shared<Reader>();auto input=original_channel_source(reader);const LinearUnmixModel model(matrix());auto source=linear_unmix_channel_source(input,model);check(source->domain()=="qpx.linear-unmixed-samples/1" && source->metadata().sample_type==SampleType::Float64 && source->metadata().channels==4,"Explicit component/residual source domain and metadata");RawRegionRequest region{{0,0,0,5,3},0,4,1,1};
    const auto work=source->read_work_bytes(region);rejects<WorkflowCaptureLimit>([&]{source->read(region,work-1);});check(reader->reads.empty(),"Work refusal precedes all pixel reads");auto full=source->read(region,work);check(reader->reads==std::vector<std::pair<std::uint32_t,std::uint32_t>>{{2,1},{7,1}},"Sparse source reads only named channel groups");
    for(int y=0;y<3;++y)for(int x=0;x<5;++x){const auto at=std::size_t(y*5+x);check(bool(full.valid()[at])==!(x==0 && y==0),"Source padding validity retained");if(full.valid()[at]){expect_close(values(full)[at*4],(x-2)*10+8);expect_close(values(full)[at*4+1],y*4+3);expect_close(values(full)[at*4+2],0);expect_close(values(full)[at*4+3],0);}}
    auto component=region;component.first_channel=1;component.channels=1;auto one=source->read(component);for(std::size_t p=0;p<one.valid().size();++p)check(values(one)[p]==values(full)[p*4+1],"Component source slice equals full output");
    for(int y=0;y<3;++y)for(int x=0;x<5;x+=2){auto r=region;r.region={x,y,0,std::min(2,5-x),1};auto tile=source->read(r);for(std::size_t p=0;p<tile.valid().size();++p){auto global=std::size_t(y*5+x)+p;check(tile.valid()[p]==full.valid()[global],"Tile source validity equality");for(int c=0;c<4;++c)check(values(tile)[p*4+c]==values(full)[global*4+c],"Exact tile/whole source equality");}}
    auto permutation=matrix();std::swap(permutation.inputs[0],permutation.inputs[1]);permutation.coefficients={.5,1,1,.25};auto permuted=linear_unmix_channel_source(input,permutation);auto reordered=permuted->read(region);for(std::size_t p=0;p<full.valid().size();++p)if(full.valid()[p]){expect_close(values(reordered)[p*4],values(full)[p*4]);expect_close(values(reordered)[p*4+1],values(full)[p*4+1]);}check(permuted->sha256()!=source->sha256(),"Explicit row order has a distinct recipe identity");
    auto contiguous_reader=std::make_shared<Reader>();contiguous_reader->second=3;auto contiguous_matrix=matrix();contiguous_matrix.inputs[1]={3,"C3"};auto contiguous=linear_unmix_channel_source(original_channel_source(contiguous_reader),contiguous_matrix);auto direct=contiguous->read(region,contiguous->read_work_bytes(region));check(contiguous_reader->reads==std::vector<std::pair<std::uint32_t,std::uint32_t>>{{2,2}},"Contiguous source uses one direct read without a gather copy");for(std::size_t i=0;i<values(full).size();++i)check(values(direct)[i]==values(full)[i],"Direct and sparse-gather paths agree exactly");
    std::swap(contiguous_matrix.inputs[0],contiguous_matrix.inputs[1]);contiguous_matrix.coefficients={.5,1,1,.25};auto direct_permuted=linear_unmix_channel_source(original_channel_source(contiguous_reader),contiguous_matrix)->read(region);for(std::size_t pixel=0;pixel<full.valid().size();++pixel)if(full.valid()[pixel]){expect_close(values(direct_permuted)[pixel*4],values(full)[pixel*4]);expect_close(values(direct_permuted)[pixel*4+1],values(full)[pixel*4+1]);}
    auto wrong=matrix();wrong.inputs[0].name="Wrong";rejects<std::invalid_argument>([&]{linear_unmix_channel_source(input,wrong);});wrong=matrix();wrong.input_domain="qpx.dark-flat-corrected-samples/1";rejects<std::invalid_argument>([&]{linear_unmix_channel_source(input,wrong);});
    auto corrected=dark_flat_channel_source(input,original_channel_source(std::make_shared<Reader>(1)),original_channel_source(std::make_shared<Reader>(2)),{std::vector<double>(10,1),0});auto recipe=matrix();recipe.input_domain=corrected->domain();auto corrected_unmix=linear_unmix_channel_source(corrected,recipe);auto corrected_out=corrected_unmix->read(region);expect_close(values(corrected_out)[6*4],-20./7);expect_close(values(corrected_out)[6*4+1],45./7);
    std::atomic<bool> cancel{true};rejects<WorkflowCancelled>([&]{source->read(region,work,&cancel);});cancel.store(false);reader->cancel_on_read=&cancel;rejects<WorkflowCancelled>([&]{source->read(region,work,&cancel);});reader->cancel_on_read=nullptr;
    reader->wrong_shape=true;rejects<WorkflowInputChanged>([&]{source->read(region);});reader->wrong_shape=false;reader->change=true;rejects<WorkflowInputChanged>([&]{source->read(region);});reader->raw.pixel_width_um=.5;
    reader->observed=make_reader_source("unmix-reference","","memory");rejects<WorkflowInputChanged>([&]{source->read(region);});reader->close();rejects<WorkflowInputChanged>([&]{source->read(region);});
}
int main(){try{schema();records();if(!has_linear_unmixing()){rejects<std::runtime_error>([&]{LinearUnmixModel unsupported(matrix());});std::cout<<"Matrix schema/identity and disabled native capability refusal pass; numerical backend unavailable\n";return 0;}numeric();sources();std::cout<<"Native SVD unmixing: signed analytical mixtures, least-squares residuals, condition/rank, permutations, source groups/tiles, work, precision, cancellation and source guards pass\n";}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
